<?php
require_once __DIR__.'/../includes/admin-layout.php';
admin_require();$schemaReady=control_tables_available();
$counts=[];foreach(['users','images','albums','reports','relays'] as $table){try{$counts[$table]=(int)db()->query("SELECT COUNT(*) FROM $table")->fetchColumn();}catch(Throwable){$counts[$table]=0;}}
$ready=(int)db()->query('SELECT COUNT(*) FROM images WHERE status="ready"')->fetchColumn();$bytes=(int)db()->query('SELECT COALESCE(SUM(size),0) FROM images WHERE status!="deleted"')->fetchColumn();$recent=db()->query('SELECT i.short_id,i.original_filename,i.size,i.status,i.created_at,u.email FROM images i LEFT JOIN users u ON u.id=i.user_id ORDER BY i.id DESC LIMIT 8')->fetchAll();
try{$activity=db()->query('SELECT email,event,created_at FROM auth_activity ORDER BY id DESC LIMIT 8')->fetchAll();}catch(Throwable){$activity=[];}
$banned=0;$trafficSummary=['day'=>['hits'=>0,'unique'=>0,'images'=>0],'week'=>['hits'=>0,'unique'=>0,'images'=>0],'month'=>['hits'=>0,'unique'=>0,'images'=>0]];
$range=in_array($_GET['range']??'week',['day','week','month'],true)?$_GET['range']:'week';$chart=[];
if($schemaReady){
    try{
        $banned=(int)db()->query('SELECT COUNT(DISTINCT user_id) FROM user_bans WHERE active=1 AND starts_at<=UTC_TIMESTAMP() AND (expires_at IS NULL OR expires_at>UTC_TIMESTAMP())')->fetchColumn();
        $windows=['day'=>'DATE_SUB(UTC_TIMESTAMP(),INTERVAL 24 HOUR)','week'=>'DATE_SUB(UTC_TIMESTAMP(),INTERVAL 7 DAY)','month'=>'DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)'];
        foreach($windows as $key=>$start){$row=db()->query("SELECT COALESCE(SUM(hits),0) hits,COUNT(DISTINCT visitor_hash) unique_visitors,COALESCE(SUM(image_hits),0) image_hits FROM traffic_hourly WHERE bucket_hour >= $start")->fetch();$trafficSummary[$key]=['hits'=>(int)$row['hits'],'unique'=>(int)$row['unique_visitors'],'images'=>(int)$row['image_hits']];}
        if($range==='day'){$start=$windows['day'];$group='DATE_FORMAT(bucket_hour,"%Y-%m-%d %H:00:00")';$labelFormat='H:i';$steps=24;$interval='hour';}
        elseif($range==='month'){$start=$windows['month'];$group='DATE(bucket_hour)';$labelFormat='d M';$steps=30;$interval='day';}
        else{$start=$windows['week'];$group='DATE(bucket_hour)';$labelFormat='D';$steps=7;$interval='day';}
        $series=db()->query("SELECT $group bucket,COALESCE(SUM(hits),0) hits,COUNT(DISTINCT visitor_hash) unique_visitors FROM traffic_hourly WHERE bucket_hour >= $start GROUP BY bucket ORDER BY bucket")->fetchAll();$seriesMap=[];foreach($series as $item)$seriesMap[(string)$item['bucket']]=$item;
        $cursor=$interval==='hour'?(new DateTimeImmutable('now',new DateTimeZone('UTC')))->setTime((int)gmdate('H'),0):(new DateTimeImmutable('today',new DateTimeZone('UTC')));
        for($i=$steps-1;$i>=0;$i--){$date=$cursor->modify('-'.$i.' '.$interval);$key=$interval==='hour'?$date->format('Y-m-d H:00:00'):$date->format('Y-m-d');$item=$seriesMap[$key]??['hits'=>0,'unique_visitors'=>0];$chart[]=['label'=>$date->format($labelFormat),'hits'=>(int)$item['hits'],'unique'=>(int)$item['unique_visitors']];}
    }catch(Throwable $error){$schemaReady=false;app_log('Admin analytics failed: '.$error->getMessage());}
}
$maxHits=max(1,...array_column($chart,'hits'));
admin_start('Genel bakış');admin_title('IMGTR CONTROL CENTER','Genel bakış','Üyeler, içerikler, trafik ve dağıtık depolama durumunu tek ekrandan izleyin.');
?>
<?php if(!$schemaReady):?><div class="admin-schema-warning"><b>Gelişmiş admin şeması kurulmamış.</b><code>updates/2026-08-31-admin-control.sql</code></div><?php endif?>
<section class="admin-stats"><article><span>Üyeler</span><strong><?=number_format($counts['users'])?></strong><small><?=$counts['albums']?> albüm · <?=$banned?> kısıtlı</small></article><article><span>Görseller</span><strong><?=number_format($counts['images'])?></strong><small><?=$ready?> erişilebilir</small></article><article><span>Depolanan veri</span><strong><?=e(format_bytes($bytes))?></strong><small><?=$counts['relays']?> bağımsız nokta</small></article><article><span>Açık bildirim</span><strong><?=number_format($counts['reports'])?></strong><small>İnceleme kuyruğu</small></article></section>
<?php if($schemaReady):?><section class="traffic-summary"><article><span>Son 24 saat</span><strong><?=number_format($trafficSummary['day']['hits'])?> hit</strong><small><?=number_format($trafficSummary['day']['unique'])?> tekil · <?=number_format($trafficSummary['day']['images'])?> görsel</small></article><article><span>Son 7 gün</span><strong><?=number_format($trafficSummary['week']['hits'])?> hit</strong><small><?=number_format($trafficSummary['week']['unique'])?> tekil · <?=number_format($trafficSummary['week']['images'])?> görsel</small></article><article><span>Son 30 gün</span><strong><?=number_format($trafficSummary['month']['hits'])?> hit</strong><small><?=number_format($trafficSummary['month']['unique'])?> tekil · <?=number_format($trafficSummary['month']['images'])?> görsel</small></article></section>
<section class="traffic-panel"><div class="traffic-panel-head"><div><p class="eyebrow">TRAFİK / UTC</p><h2>Tekil ziyaretçi ve toplam hit</h2></div><div><nav class="admin-periods"><a class="<?=$range==='day'?'active':''?>" href="?range=day">Günlük</a><a class="<?=$range==='week'?'active':''?>" href="?range=week">Haftalık</a><a class="<?=$range==='month'?'active':''?>" href="?range=month">Aylık</a></nav><p class="traffic-legend"><span><i></i>Toplam hit</span><span><i></i>Tekil</span></p></div></div><div class="traffic-chart"><?php if(!$chart):?><div class="traffic-empty">Henüz trafik verisi yok.</div><?php else:foreach($chart as $point):$hitHeight=round($point['hits']/$maxHits*100,2);$uniqueHeight=round($point['unique']/$maxHits*100,2);?><div class="traffic-bar" title="<?=e($point['label'])?> · <?=$point['hits']?> hit · <?=$point['unique']?> tekil"><div class="traffic-columns"><i style="--total:<?=$hitHeight?>%"></i><i style="--unique:<?=$uniqueHeight?>%"></i></div><small><?=e($point['label'])?></small></div><?php endforeach;endif?></div></section><?php endif?>
<div class="admin-columns"><section class="admin-card"><div class="card-heading"><h2>Son yüklenen görseller</h2><a href="/admin/images">Tümünü gör →</a></div><div class="admin-feed"><?php foreach($recent as $row):?><a href="<?=$row['status']==='ready'?'/'.e($row['short_id']):'/admin/images'?>"><span class="file-icon">IMG</span><div><b><?=e($row['original_filename'])?></b><small><?=e($row['email']?:'Anonim')?> · <?=e(format_bytes((int)$row['size']))?></small></div><em class="status-<?=e($row['status'])?>"><?=e($row['status'])?></em></a><?php endforeach?></div></section><section class="admin-card"><div class="card-heading"><h2>Son hesap hareketleri</h2><a href="/admin/activity">Kayıtlar →</a></div><?php if(!$activity):?><div class="admin-empty">Henüz kimlik doğrulama kaydı yok.</div><?php else:?><div class="admin-feed"><?php foreach($activity as $row):?><div class="activity-row"><span class="activity-icon"><i class="fa-solid fa-clock-rotate-left"></i></span><div><b><?=e($row['email']?:'Bilinmeyen kullanıcı')?></b><small><?=e($row['event'])?></small></div><time><?=e($row['created_at'])?></time></div><?php endforeach?></div><?php endif?></section></div>
<?php admin_end();
